messages.content:
Tool response:
Tool: create_coupon
Description: Create Coupon
Parameters:
    {
      "type": "object",
      "properties": {
        "code": {
          "type": "string",
          "title": "Code",
          "description": "Unique coupon code"
        },
        "discount_type": {
          "type": "string",
          "title": "Discount Type",
          "description": "Type of discount ('percentage' or 'fixed')"
        },
        "discount_value": {
          "type": "number",
          "title": "Discount Value",
          "description": "Discount amount (percentage or fixed value)"
        },
        "valid_until": {
          "type": "string",
          "title": "Valid Until",
          "description": "Expiration date of the coupon in ISO format"
        }
      },
      "required": [
        "code",
        "discount_type",
        "discount_value",
        "valid_until"
      ]
    }
